INSERT INTO public.saved_recommendations (id, user_id, oasis_code, label, description, main_duties, role_creativity, role_leadership, role_digital_literacy, role_critical_thinking, role_problem_solving, saved_at, analytical_thinking, attention_to_detail, collaboration, adaptability, independence, evaluation, decision_making, stress_tolerance, all_fields, personal_analysis, entry_qualifications, suggested_improvements, source_type, graphsage_top_skills, feasibility_analysis, time_to_qualification, education_required, match_score, source_tool, conversation_id, component_type, component_data, interaction_metadata) VALUES (146, 21, '21211.0', 'Data scientists', '', 'Implement cutting-edge techniques and tools in machine learning, deep learning and artificial intelligence to make data analysis more efficient | Perform large-scale experimentation to identify hidden relationships between variables in large datasets | Create advanced machine learning algorithms such as regression, simulation, scenario analysis, modeling, clustering, decision trees and , neural networks | Prepare and extract data using programming language | Implement new statistical, machine learning, or other mathematical methodologies to solve specific business problems | Visualize data in a way that allows a business to quickly draw conclusions and make decisions | Develop artificial intelligence models and algorithms and implement them to meet the needs of the organization', 4, 0, 0, 0, 0, '2025-05-13 10:00:38.334857-04', 5, 5, 3, 4, 0, 0, 0, 0, '{"oasis_code": "21211", "oasis_label__final_x": "Data scientists", "job_title_text": "data mining analyst | data miner | data scientist | artificial intelligence (AI) designer | big data engineer | big data analyst | data analytics specialist | machine learning engineer | machine learning specialist | quantitative analyst | data architect | artificial intelligence (AI) consultant | artificial intelligence (AI) analyst | lead data scientist | big data developer | data analytics consultant | data engineer | data modeler", "main_duties": "Implement cutting-edge techniques and tools in machine learning, deep learning and artificial intelligence to make data analysis more efficient | Perform large-scale experimentation to identify hidden relationships between variables in large datasets | Create advanced machine learning algorithms such as regression, simulation, scenario analysis, modeling, clustering, decision trees and , neural networks | Prepare and extract data using programming language | Implement new statistical, machine learning, or other mathematical methodologies to solve specific business problems | Visualize data in a way that allows a business to quickly draw conclusions and make decisions | Develop artificial intelligence models and algorithms and implement them to meet the needs of the organization", "employment_requirement": "A bachelor''s degree in statistics, mathematics, computer science, computer systems engineering or a related discipline or completion of a college program in computer science is usually required", "active_learning": "4", "adaptability": "4", "analytical_thinking": "5", "attention_to_detail": "5", "creativity": "4", "concern_for_others": "2", "collaboration": "3"}', NULL, NULL, NULL, 'esco', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.saved_recommendations (id, user_id, oasis_code, label, description, main_duties, role_creativity, role_leadership, role_digital_literacy, role_critical_thinking, role_problem_solving, saved_at, analytical_thinking, attention_to_detail, collaboration, adaptability, independence, evaluation, decision_making, stress_tolerance, all_fields, personal_analysis, entry_qualifications, suggested_improvements, source_type, graphsage_top_skills, feasibility_analysis, time_to_qualification, education_required, match_score, source_tool, conversation_id, component_type, component_data, interaction_metadata) VALUES (151, 21, '21232.0', 'Software developers and programmers', '', 'Design, write, read, test, and correct code for new software | Analyze information to recommend and plan the installation of new systems or modifications of an existing system | Evaluate simple interrelationships between programs such as whether a contemplated change in one part of a program would cause unwanted results in a related part | Program animation software to predefined specifications for interactive video games, Internet and mobile applications | Write, modify, integrate and test software code for e-commerce, Internet and mobile applications | Develop, implement, modify and maintain gameplay features that integrate effectively into existing software | Write documentation for new and updated software', 3, 0, 0, 0, 0, '2025-05-13 10:01:16.083765-04', 5, 5, 3, 4, 4, 0, 0, 0, '{"oasis_code": "21232", "oasis_label__final_x": "Software developers and programmers", "job_title_text": "application programmer | computer application programmer | software development programmer | software programmer | teleprocessing software programmer | interactive media developer | electronic commerce (e-commerce) software developer | computer game developer | animation programmer | special effects programmer | interactive media programmer | multimedia developer | multimedia programmer | software developer | electronic business (e-business) software developer | graphical user interface (GUI) designer | graphical user interface (GUI) developer | mobile applications developer | cloud developer | software development project manager | computer game programmer | artificial intelligence programmer | graphics programmer", "main_duties": "Design, write, read, test, and correct code for new software | Analyze information to recommend and plan the installation of new systems or modifications of an existing system | Evaluate simple interrelationships between programs such as whether a contemplated change in one part of a program would cause unwanted results in a related part | Program animation software to predefined specifications for interactive video games, Internet and mobile applications | Write, modify, integrate and test software code for e-commerce, Internet and mobile applications | Develop, implement, modify and maintain gameplay features that integrate effectively into existing software | Write documentation for new and updated software", "employment_requirement": "A bachelor''s degree in computer science or software engineering or in another discipline with a significant programming component or completion of a college program in computer science or related field is usually required", "active_learning": "3", "adaptability": "4", "analytical_thinking": "5", "attention_to_detail": "5", "creativity": "3", "concern_for_others": "3", "collaboration": "3", "independence": "4", "innovativeness": "4"}', NULL, NULL, NULL, 'esco', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
