INSERT INTO public.tree_paths (id, user_id, tree_type, tree_json, name, created_at) VALUES ('c6e0be5f-a83b-4209-b62a-98048415e9f0', 10, 'skills', '{"id": "root", "label": "Aspiring Investment Banker", "type": "root", "level": 0, "actions": [], "children": [{"id": "skill-financial-accounting", "label": "Understand Financial Accounting", "type": "skill", "level": 0, "actions": ["Complete ''Financial Accounting'' on Coursera", "Read ''Financial Accounting for Dummies''", "Analyze annual reports of top banks"], "children": [{"id": "skill-financial-modeling", "label": "Develop Financial Modeling Skills", "type": "skill", "level": 0, "actions": ["Take ''Financial Modeling & Valuation Analyst'' by CFI", "Build a financial model using Excel", "Analyze a company''s financial health using modeling"], "children": [{"id": "career-financial-analyst", "label": "Financial Analyst", "type": "outcome", "level": 0, "actions": [], "children": [{"id": "skill-quantitative-analysis", "label": "Learn Quantitative Analysis", "type": "skill", "level": 0, "actions": ["Complete ''Quantitative Finance'' by MIT OpenCourseWare", "Read ''Quantitative Finance for Dummies''", "Build trading algorithms using Python"], "children": [{"id": "skill-risk-management", "label": "Master Risk Management", "type": "skill", "level": 0, "actions": ["Study ''Risk Management'' by GARP", "Implement risk assessment models in Excel", "Conduct stress tests on financial models"], "children": [{"id": "career-investment-banker", "label": "Investment Banker", "type": "outcome", "level": 0, "actions": []}]}]}]}]}]}, {"id": "skill-economics-theory", "label": "Study Economics Theory", "type": "skill", "level": 0, "actions": ["Complete ''Principles of Economics'' at edX", "Read ''Economics in One Lesson'' by Henry Hazlitt", "Participate in economics discussion groups"], "children": [{"id": "skill-macroeconomics", "label": "Deep Dive into Macroeconomics", "type": "skill", "level": 0, "actions": ["Take ''Macroeconomics'' by MI