INSERT INTO public.user_skill_trees (id, user_id, graph_id, tree_data, created_at) VALUES (21, 22, 'e5e85639-1040-41ec-afb0-c78b5651e271', '"{\"nodes\": [{\"id\": \"skill::key_4884\", \"skill_id\": \"skill::key_4884\", \"skill_label\": \"skill::key_4884\", \"challenge\": \"Pour d\\u00e9velopper votre comp\\u00e9tence en programmation, le d\\u00e9fi consiste \\u00e0 cr\\u00e9er une application de bureau simple en utilisant un langage de programmation de votre choix. L''application devrait avoir une interface utilisateur, une fonctionnalit\\u00e9 de connexion, et au moins trois fonctionnalit\\u00e9s suppl\\u00e9mentaires de votre choix.\", \"xp_reward\": 42, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\", \"graph_id\": \"e5e85639-1040-41ec-afb0-c78b5651e271\"}, {\"id\": \"skill::key_13434\", \"skill_id\": \"skill::key_13434\", \"skill_label\": \"skill::key_13434\", \"challenge\": \"Recherchez et suivez un tutoriel en ligne sur skill::key_13434. Pratiquez les concepts appris pendant au moins 3 heures.\", \"xp_reward\": 45, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\", \"graph_id\": \"e5e85639-1040-41ec-afb0-c78b5651e271\"}, {\"id\": \"skill::key_11815\", \"skill_id\": \"skill::key_11815\", \"skill_label\": \"skill::key_11815\", \"challenge\": \"D\\u00e9veloppez un programme ou une application simple qui r\\u00e9sout un probl\\u00e8me quotidien. Vous pouvez choisir un langage de programmation de votre choix. Assurez-vous d''incorporer une vari\\u00e9t\\u00e9 de fonctionnalit\\u00e9s et de travailler sur l''am\\u00e9lioration de l''interface utilisateur et de l''exp\\u00e9rience.\", \"xp_reward\": 43, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\", \"graph_id\": \"e5e85639-1040-41ec-afb0-c78b5651e271\"}, {\"id\": \"skill::key_11326\", \"skill_id\": \"skill::key_11326\", \"skill_label\": \"skill::key_11326\", \"challenge\": \"Votre d\\u00e9fi est de concevoir et de r\\u00e9diger un projet de recherche d\\u00e9taill\\u00e9 sur un sujet de votre choix. Ce projet doit comprendre une introduction, une revue de litt\\u00e9rature, une hypoth\\u00e8se, une m\\u00e9thodologie, des pr\\u00e9visions de r\\u00e9sultats et une conclusion.\", \"xp_reward\": 74, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\", \"graph_id\": \"e5e85639-1040-41ec-afb0-c78b5651e271\"}, {\"id\": \"skill::key_8161\", \"skill_id\": \"skill::key_8161\", \"skill_label\": \"skill::key_8161\", \"challenge\": \"Recherchez et suivez un tutoriel en ligne sur skill::key_8161. Pratiquez les concepts appris pendant au moins 3 heures.\", \"xp_reward\": 56, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\", \"graph_id\": \"e5e85639-1040-41ec-afb0-c78b5651e271\"}], \"edges\": [], \"graph_id\": \"e5e85639-1040-41ec-afb0-c78b5651e271\"}"', '2025-05-30 17:19:16.083643');
INSERT INTO public.user_skill_trees (id, user_id, graph_id, tree_data, created_at) VALUES (22, 25, 'abe8cc7e-b1e2-4c57-91f1-0a8408a41657', '"{\"nodes\": {\"skill::key_7226\": {\"id\": \"skill::key_7226\", \"type\": \"skill\", \"label\": \"apply strategic thinking\", \"metadata\": {\"label\": \"apply strategic thinking\", \"type\": \"skill\", \"originuri\": \"http://data.europa.eu/esco/skill/6c870993-9341-438b-91c0-c7fe4f96d8f5\", \"uuidhistory\": \"a71b991a-32ab-4549-be36-4e1937acc883\\n964c1d63-681d-4f91-9a0a-0ab87a57fcd8\", \"skilltype\": \"skill/competence\", \"reuselevel\": \"cross-sector\", \"preferredlabel\": \"apply strategic thinking\", \"altlabels\": \"apply strategic thinking techniques\\napply strategic thinking\\napply techniques for strategic thinking\\nmove strategically\\nthink strategically\", \"description\": \"Apply generation and effective application of business insights and possible opportunities, in order to achieve competitive business advantage on a long-term basis.\", \"definition\": \"\", \"scopenote\": \"\", \"islocalized\": \"false\"}, \"is_anchor\": true, \"depth\": 0, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez apply strategic thinking pendant une semaine.\", \"xp_reward\": 25, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\"}, \"skill::key_3396\": {\"id\": \"skill::key_3396\", \"type\": \"skill\", \"label\": \"imprint visionary aspirations into the business management\", \"metadata\": {\"label\": \"imprint visionary aspirations into the business management\", \"type\": \"skill\", \"originuri\": \"http://data.europa.eu/esco/skill/272fddbb-917a-4720-8903-85ce51e1cbe5\", \"uuidhistory\": \"243f804c-eb4a-4aa4-a98d-0cf4ac8ede1d\\nf928e14c-5f17-43d7-9e64-399771525daf\", \"skilltype\": \"skill/competence\", \"reuselevel\": \"cross-sector\", \"preferredlabel\": \"imprint visionary aspirations into the business management\", \"altlabels\": \"imprinting visionary aspirations into the business management\\nimprint visionary aspiration into the business management\\nincorporate visionary aspirations into the business management\\nimprint business management visionary aspirations\\nimprint visionary goals into the business management\\nimprint visionary aspirations into the business management\\nIntegrate visionary aspirations into the business management\", \"description\": \"Integrate ambition and visionary plans in both the planning and the day-to-day operations in order to set goals for the company to strive for.\", \"definition\": \"\", \"scopenote\": \"\", \"islocalized\": \"false\"}, \"is_anchor\": true, \"depth\": 0, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez imprint visionary aspirations into the business management pendant une semaine.\", \"xp_reward\": 25, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\"}, \"skill::key_1812\": {\"id\": \"skill::key_1812\", \"type\": \"skill\", \"label\": \"carry out strategic research\", \"metadata\": {\"label\": \"carry out strategic research\", \"type\": \"skill\", \"originuri\": \"http://data.europa.eu/esco/skill/0aa02c52-077d-45f8-8c2d-7132c11ac16e\", \"uuidhistory\": \"39aef8a9-4b26-436b-9684-ab5cb9de6f56\\n86fb0a7c-662b-4f3f-b4b2-31deebebfb2d\", \"skilltype\": \"skill/competence\", \"reuselevel\": \"cross-sector\", \"preferredlabel\": \"carry out strategic research\", \"altlabels\": \"carrying out strategic research\\ncarry out a research strategy\\nconduct strategic research\\ncarry out strategic research\\ncomplete strategic research\\nundertake strategic research\\noversee strategic research\", \"description\": \"Research long term possibilities for improvements and plan steps to achieve them.\", \"definition\": \"\", \"scopenote\": \"\", \"islocalized\": \"false\"}, \"is_anchor\": true, \"depth\": 0, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez carry out strategic research pendant une semaine.\", \"xp_reward\": 25, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\"}, \"skill::key_14161\": {\"id\": \"skill::key_14161\", \"type\": \"skill\", \"label\": \"align efforts towards business development\", \"metadata\": {\"label\": \"align efforts towards business development\", \"type\": \"skill\", \"originuri\": \"http://data.europa.eu/esco/skill/ee7f90cc-922e-4da7-a7ae-83c2688fed10\", \"uuidhistory\": \"e1f00a68-1211-439a-8945-7f7929d1504e\\n56630ed7-f513-4aa7-9cfb-aa9aa932102d\", \"skilltype\": \"skill/competence\", \"reuselevel\": \"cross-sector\", \"preferredlabel\": \"align efforts towards business development\", \"altlabels\": \"align business development efforts\\naligning efforts towards business development\\nalign efforts towards business development\\nalign effort towards business development\\ncoordinate efforts towards business development\\nalign efforts towards business growth\", \"description\": \"Synchronise the efforts, plans, strategies, and actions carried out in departments of companies towards the growth of business and its turnover. Keep business development as the ultimate outcome of any effort of the company.\", \"definition\": \"\", \"scopenote\": \"\", \"islocalized\": \"false\"}, \"is_anchor\": true, \"depth\": 0, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez align efforts towards business development pendant une semaine.\", \"xp_reward\": 25, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\"}, \"skill::key_9632\": {\"id\": \"skill::key_9632\", \"type\": \"skill\", \"label\": \"assist clients with personal development\", \"metadata\": {\"label\": \"assist clients with personal development\", \"type\": \"skill\", \"originuri\": \"http://data.europa.eu/esco/skill/98b32477-cccd-47ea-8c85-d4a16b18af08\", \"uuidhistory\": \"03a93930-9edd-43a6-8657-a5048f1c3750\\n2528dee4-f0dc-49ff-ba82-46e811456d51\", \"skilltype\": \"skill/competence\", \"reuselevel\": \"sector-specific\", \"preferredlabel\": \"assist clients with personal development\", \"altlabels\": \"assist with personal development of clients\\naid clients with personal development\\nhelp clients with personal development\\nassist client with personal development\\nassisting clients with personal development\\nassist clients with personal development\", \"description\": \"Help clients determine what they want to do with their lives and assist in setting personal and professional goals, by prioritising and planning the steps necessary to reach these goals.\", \"definition\": \"\", \"scopenote\": \"\", \"islocalized\": \"false\"}, \"is_anchor\": true, \"depth\": 0, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez assist clients with personal development pendant une semaine.\", \"xp_reward\": 25, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\"}, \"skillgroup::key_1018\": {\"id\": \"skillgroup::key_1018\", \"type\": \"skillgroup\", \"label\": \"developing objectives and strategies\", \"metadata\": {\"label\": \"developing objectives and strategies\", \"type\": \"skillgroup\", \"originuri\": \"http://data.europa.eu/esco/skill/6ee936b0-4e0c-4e04-97c7-1f4ee9230d67\", \"uuidhistory\": \"3a012fff-b177-4cf7-950f-8ebb35fe3510\\nf020253a-e05c-4447-82bd-777648b45045\", \"code\": \"S4.1.0\", \"preferredlabel\": \"developing objectives and strategies\", \"altlabels\": \"strategic planning\\ndeveloping objectives and strategies\", \"description\": \"Envisioning a future state and developing strategies, goals, objectives and action plans to achieve it.\", \"scopenote\": \"\"}, \"is_anchor\": false, \"depth\": 1, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez developing objectives and strategies pendant une semaine.\", \"xp_reward\": 25, \"visible\": false, \"revealed\": false, \"state\": \"locked\", \"notes\": \"\"}, \"occupation::key_16131\": {\"id\": \"occupation::key_16131\", \"type\": \"occupation\", \"label\": \"strategic planning manager\", \"metadata\": {\"label\": \"strategic planning manager\", \"type\": \"occupation\", \"originuri\": \"http://data.europa.eu/esco/occupation/4f49df98-98b8-4a9e-98ad-9c5557817eba\", \"uuidhistory\": \"8c3c9ea3-8453-4409-9419-d9ca909dab20\\ne86026ef-9489-4599-a13f-5325397c2113\", \"occupationgroupcode\": \"1213\", \"code\": \"1213.2.2\", \"preferredlabel\": \"strategic planning manager\", \"altlabels\": \"strategic planning manager\\nstrategic manager\\nbusiness continuity strategy director\\ncorporate strategist\\nbusiness continuity planning director\\nstrategy manager\\nstrategic development manager\\ninnovation and strategy specialist\\nplanning manager\\nstrategy adviser\\nstrategic business planning manager\", \"description\": \"Strategic planning managers create, together with a team of managers, the strategic plans of the company as a whole, and provide coordination in the implementation per department. They help to interpret the overall plan and create a detailed plan for each one of the departments and branches. They ensure consistency in the implementation.\", \"definition\": \"\", \"scopenote\": \"\", \"regulatedprofessionnote\": \"http://data.europa.eu/esco/regulated-professions/unregulated\", \"occupationtype\": \"escooccupation\", \"islocalized\": \"false\"}, \"is_anchor\": false, \"depth\": 1, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez strategic planning manager pendant une semaine.\", \"xp_reward\": 25, \"visible\": false, \"revealed\": false, \"state\": \"locked\", \"notes\": \"\"}, \"occupation::key_17610\": {\"id\": \"occupation::key_17610\", \"type\": \"occupation\", \"label\": \"policy officer\", \"metadata\": {\"label\": \"policy officer\", \"type\": \"occupation\", \"originuri\": \"http://data.europa.eu/esco/occupation/caf7b8fb-b2d6-46b7-bffa-bea7f8e4aed8\", \"uuidhistory\": \"4e10bba3-027a-4326-9a9f-2eeba0d8c0f8\\nf63c7116-8f24-4e24-80e2-5e0e6ac022e4\", \"occupationgroupcode\": \"2422\", \"code\": \"2422.12\", \"preferredlabel\": \"policy officer\", \"altlabels\": \"policy analyst\\nhealth policy officer\\npolicy researcher\\npolicy coordinator\\npolicy manager\\nstrategy advisor\\npolicy officer\\nstrategy manager\\npolicy advisor\", \"description\": \"Policy officers research, analyse and develop policies in various public sectors, and shape and implement these policies to improve the existing regulation around the sector. They evaluate effects of existing policies and report findings to the government and members of the public. Policy officers work closely with partners, external organisations or other stakeholders and provide them with regular updates.\", \"definition\": \"\", \"scopenote\": \"\", \"regulatedprofessionnote\": \"http://data.europa.eu/esco/regulated-professions/unregulated\", \"occupationtype\": \"escooccupation\", \"islocalized\": \"false\"}, \"is_anchor\": false, \"depth\": 1, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez policy officer pendant une semaine.\", \"xp_reward\": 25, \"visible\": false, \"revealed\": false, \"state\": \"locked\", \"notes\": \"\"}, \"skillgroup::key_1119\": {\"id\": \"skillgroup::key_1119\", \"type\": \"skillgroup\", \"label\": \"collaborating and liaising\", \"metadata\": {\"label\": \"collaborating and liaising\", \"type\": \"skillgroup\", \"originuri\": \"http://data.europa.eu/esco/skill/af84405b-896d-4ed3-9462-077ea9a2a188\", \"uuidhistory\": \"ed2a8e7c-a98d-4885-8c03-a594784da771\\na8fc43d3-0ef2-47af-8f36-43ec997ed7b1\", \"code\": \"S1.2.5\", \"preferredlabel\": \"collaborating and liaising\", \"altlabels\": \"collaborating and liaising\", \"description\": \"Reaching out to outside agencies, clients and other organisational units to facilitate exchange of information. Collaborating and engaging with external and internal agencies and departments to adapt the timing and nature of the activities.\", \"scopenote\": \"Examples: \\n- contact event speakers\\n- liaise with auditors\"}, \"is_anchor\": false, \"depth\": 1, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez collaborating and liaising pendant une semaine.\", \"xp_reward\": 25, \"visible\": false, \"revealed\": false, \"state\": \"locked\", \"notes\": \"\"}, \"occupation::key_16303\": {\"id\": \"occupation::key_16303\", \"type\": \"occupation\", \"label\": \"career guidance advisor\", \"metadata\": {\"label\": \"career guidance advisor\", \"type\": \"occupation\", \"originuri\": \"http://data.europa.eu/esco/occupation/5d0cc30d-068a-424c-8463-f42872a7149e\", \"uuidhistory\": \"61d8ffee-ade6-4f68-ae44-59c8d73c0d03\\n9e99e511-7f0c-4b10-9cd5-f912d921fd80\", \"occupationgroupcode\": \"2423\", \"code\": \"2423.1\", \"preferredlabel\": \"career guidance advisor\", \"altlabels\": \"school careers advisor\\ncareers officer\\ncareer coach\\ncareer guidance advisor\\ncareers advisor\\ncareer guidance education advisor\\neducational advisor\\ncareer guidance practitioner\\nmentor for prior learning\\ncareer guidance counsellor\\nschool career guidance advisor\\ncounsellor in career guidance\", \"description\": \"Career guidance advisors provide guidance and advice to adults and students on making educational, training and occupational choices and assist people in managing their careers, through career planning and career exploration. They help identify options for future careers, assist beneficiaries in the development of their curriculum and help people reflect on their ambitions, interests and qualifications. Career guidance advisors may provide advice on various career planning issues and make suggestions for lifelong learning if necessary, including study recommendations. They may also assist the individual in the search for a job or provide guidance and advice to prepare a candidate for recognition of prior learning.\", \"definition\": \"\", \"scopenote\": \"\", \"regulatedprofessionnote\": \"http://data.europa.eu/esco/regulated-professions/unregulated\", \"occupationtype\": \"escooccupation\", \"islocalized\": \"false\"}, \"is_anchor\": false, \"depth\": 1, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez career guidance advisor pendant une semaine.\", \"xp_reward\": 25, \"visible\": false, \"revealed\": false, \"state\": \"locked\", \"notes\": \"\"}, \"skillgroup::key_1020\": {\"id\": \"skillgroup::key_1020\", \"type\": \"skillgroup\", \"label\": \"developing objectives and strategies\", \"metadata\": {\"label\": \"developing objectives and strategies\", \"type\": \"skillgroup\", \"originuri\": \"http://data.europa.eu/esco/skill/6f89dcbe-4315-4533-8801-3aadf9190b86\", \"uuidhistory\": \"dd768f6d-6448-4a29-a920-04aa403ab586\\nffb2fd3a-5bcb-46e9-bea9-0f7d68c20417\", \"code\": \"S4.1\", \"preferredlabel\": \"developing objectives and strategies\", \"altlabels\": \"strategic planning\\ndeveloping objectives and strategies\", \"description\": \"Envisioning a future state and developing strategies, goals, objectives and action plans to achieve it.\", \"scopenote\": \"\"}, \"is_anchor\": false, \"depth\": 2, \"graph_id\": \"abe8cc7e-b1e2-4c57-91f1-0a8408a41657\", \"challenge\": \"Pratiquez developing objectives and strategies pendant une semaine.\", \"xp_reward\": 25, \"visible\": false, \"revealed\": false, \"state\": \"locked\", \"notes\": \"\"}, \"skill::key_1671\": {\"id\": \"skill::key_1671\", \"type\": \"skill\", \"label\": \"accounting department processes\", \"metadata\": {\"label\": \"accounting department processes\", \"type\": \"skill\", \"originuri\": \"http://data.europa.eu/esco/skill/08371fe9-c658-4f6a-966f-71dbb0ab683d\", \"uuidhistory\": \"918d75a6-92b1-4d23-b0bf-87999db63a90\\n2fcb7822-2f81-4233-a2f8-c33bea3ca7ca\", \"skilltype\": \"knowledge\", \"reuselevel\": \"sector-specific\", \"preferredlabel\": \"accounting department processes\", \"altlabels\": \"accounting department processes\\n