INSERT INTO public.user_skill_trees (id, user_id, graph_id, tree_data, created_at) VALUES (23, 25, 'abd1bceb-2f47-45d5-8e65-fd79a87af412', '"{\"nodes\": {\"skill::key_7226\": {\"id\": \"skill::key_7226\", \"type\": \"skill\", \"label\": \"apply strategic thinking\", \"metadata\": {\"label\": \"apply strategic thinking\", \"type\": \"skill\", \"originuri\": \"http://data.europa.eu/esco/skill/6c870993-9341-438b-91c0-c7fe4f96d8f5\", \"uuidhistory\": \"a71b991a-32ab-4549-be36-4e1937acc883\\n964c1d63-681d-4f91-9a0a-0ab87a57fcd8\", \"skilltype\": \"skill/competence\", \"reuselevel\": \"cross-sector\", \"preferredlabel\": \"apply strategic thinking\", \"altlabels\": \"apply strategic thinking techniques\\napply strategic thinking\\napply techniques for strategic thinking\\nmove strategically\\nthink strategically\", \"description\": \"Apply generation and effective application of business insights and possible opportunities, in order to achieve competitive business advantage on a long-term basis.\", \"definition\": \"\", \"scopenote\": \"\", \"islocalized\": \"false\"}, \"is_anchor\": true, \"depth\": 0, \"graph_id\": \"abd1bceb-2f47-45d5-8e65-fd79a87af412\", \"challenge\": \"Recherchez et suivez un tutoriel en ligne sur apply strategic thinking. Pratiquez les concepts appris pendant au moins 3 heures.\", \"xp_reward\": 39, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\"}, \"skill::key_3396\": {\"id\": \"skill::key_3396\", \"type\": \"skill\", \"label\": \"imprint visionary aspirations into the business management\", \"metadata\": {\"label\": \"imprint visionary aspirations into the business management\", \"type\": \"skill\", \"originuri\": \"http://data.europa.eu/esco/skill/272fddbb-917a-4720-8903-85ce51e1cbe5\", \"uuidhistory\": \"243f804c-eb4a-4aa4-a98d-0cf4ac8ede1d\\nf928e14c-5f17-43d7-9e64-399771525daf\", \"skilltype\": \"skill/competence\", \"reuselevel\": \"cross-sector\", \"preferredlabel\": \"imprint visionary aspirations into the business management\", \"altlabels\": \"imprinting visionary aspirations into the business management\\nimprint visionary aspiration into the business management\\nincorporate visionary aspirations into the business management\\nimprint business management visionary aspirations\\nimprint visionary goals into the business management\\nimprint visionary aspirations into the business management\\nIntegrate visionary aspirations into the business management\", \"description\": \"Integrate ambition and visionary plans in both the planning and the day-to-day operations in order to set goals for the company to strive for.\", \"definition\": \"\", \"scopenote\": \"\", \"islocalized\": \"false\"}, \"is_anchor\": true, \"depth\": 0, \"graph_id\": \"abd1bceb-2f47-45d5-8e65-fd79a87af412\", \"challenge\": \"Recherchez et suivez un tutoriel en ligne sur imprint visionary aspirations into the business management. Pratiquez les concepts appris pendant au moins 3 heures.\", \"xp_reward\": 31, \"visible\": true, \"revealed\": true, \"state\": \"active\", \"notes\": \"\"}, \"skill::key_1812\": {\"id\": \"skill::key_1812\", \"type\": \"skill\", \"label\": \"carry out strategic research\", \"metadata\": {\"label\": \"carry out strategic research\", \"type\": \"skill\", \"originuri\": \"http://data.europa.eu/esco/skill/0aa02c52-077d-45f8-8c2d-7132c11ac16e\", \"uuidhistory\": \"39aef8a9-4b26-436b-9684-ab5cb9de6f56\\n86fb0a7c-662b-4f3f-b4b2-31deebebfb2d\", \"skilltype\": \"skill/competence\", \"reuselevel\": \"cross-sector\", \"preferredlabel\": \"carry out strategic research\", \"altlabels\": \"carrying out strategic research\\ncarry out a research strategy\\nconduct strategic research\\ncarry out strategic research\\ncomplete strategic research\\nundertake strategic research\\noversee strategic research\", \"description\": \"Research long term possibilities for improvements and plan steps to achieve them.\", \"definition\": \"\", \"scopenote\": \"\", \"islocalized\": \"false\"}, \"is_anchor