INSERT INTO public.user_skill_trees (id, user_id, graph_id, tree_data, created_at) VALUES (27, 25, '9b2e0b1a-908e-43ba-9b86-6e6756652a23', '{"edges": [], "nodes": [{"id": "skill::key_7226", "type": "skill", "depth": 0, "label": "Strategic Thinking", "notes": "", "state": "available", "visible": true, "graph_id": "9b2e0b1a-908e-43ba-9b86-6e6756652a23", "metadata": {"type": "skill", "label": "apply strategic thinking", "node_id": "skill::key_7226", "altlabels": "apply strategic thinking techniques\napply strategic thinking\napply techniques for strategic thinking\nmove strategically\nthink strategically", "originuri": "http://data.europa.eu/esco/skill/6c870993-9341-438b-91c0-c7fe4f96d8f5", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "cross-sector", "description": "Apply generation and effective application of business insights and possible opportunities, in order to achieve competitive business advantage on a long-term basis.", "islocalized": "false", "uuidhistory": "a71b991a-32ab-4549-be36-4e1937acc883\n964c1d63-681d-4f91-9a0a-0ab87a57fcd8", "preferredlabel": "apply strategic thinking"}, "revealed": true, "challenge": "Le défi consiste à choisir un projet personnel ou professionnel à réaliser dans la semaine en prenant en compte ses avantages, ses inconvénients, les ressources nécessaires et les obstacles potentiels. Le participant devra élaborer une stratégie claire pour mener à bien ce projet.", "is_anchor": true, "xp_reward": 24}, {"id": "skill::key_6843", "type": "skill", "depth": 0, "label": "Entrepreneurship", "notes": "", "state": "available", "visible": true, "graph_id": "9b2e0b1a-908e-43ba-9b86-6e6756652a23", "metadata": {"type": "skill", "label": "entrepreneurship", "node_id": "skill::key_6843", "altlabels": "entrepreneurship\nbusiness initiative\nentrepreneurialism", "originuri": "http://data.europa.eu/esco/skill/658605f2-1c95-49f0-bd98-0af7b15ad0b0", "scopenote": "", "skilltype": "knowledge", "definition": "", "reusel