INSERT INTO public.user_skill_trees (id, user_id, graph_id, tree_data, created_at) VALUES (32, 25, 'e71a1975-1f8e-4e4b-9d3b-930a338bef5c', '{"edges": [], "nodes": [{"id": "skill::key_9448", "type": "skill", "depth": 0, "label": "Strategic Leadership", "notes": "", "state": "available", "visible": true, "graph_id": "e71a1975-1f8e-4e4b-9d3b-930a338bef5c", "metadata": {"type": "skill", "label": "implement strategic management", "node_id": "skill::key_9448", "altlabels": "implement strategic management plan\ndeliver strategic management plan\ndevelop and implement strategic management plan\ndevise company development strategy\ndevise strategy for company development\ndevelop strategy for company development\nformulate and implement company development strategy\nimplement management strategy\nimplement strategic management principles\nformulate strategy for company development\nimplement strategic management", "originuri": "http://data.europa.eu/esco/skill/953445c0-4770-4be0-91cf-270a64c0e297", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "cross-sector", "description": "Implement a strategy for the development and transformation of the company. Strategic management involves the formulation and implementation of the major objectives and initiatives of a company by senior management on behalf of the owners, based on consideration of available resources and an assessment of the internal and external environments in which the organisation operates.", "islocalized": "false", "uuidhistory": "5ec05073-a8df-4a0e-9ab2-7721591dd3b6\nb0011391-93ed-4047-b65d-f977fabbe608", "preferredlabel": "implement strategic management"}, "revealed": true, "challenge": "Take the lead on a real-life project or initiative within a team or organization. This could involve organizing an event, leading a community project, or spearheading a new initiative. The focus should be on making strategic decisions, motivating and guiding the team, and achieving the desired outcomes.", "is_anchor": true, "xp_reward": 35}, {"id": "skill::key_14598", "type": "skill", "depth": 0, "label": "Strategic Decision Making", "notes": "", "state": "available", "visible": true, "graph_id": "e71a1975-1f8e-4e4b-9d3b-930a338bef5c", "metadata": {"type": "skill", "label": "make strategic business decisions", "node_id": "skill::key_14598", "altlabels": "make tactical business decisions\npay per click\nmake strategic business decisions\nmake strategic business choices\nPPC", "originuri": "http://data.europa.eu/esco/skill/f60c9e52-95fc-4ca1-a73c-18a491153b63", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "cross-sector", "description": "Analyse business information and consult directors for decision making purposes in a varied array of aspects affecting the prospect, productivity and sustainable operation of a company. Consider the options and alternatives to a challenge and make sound rational decisions based on analysis and experience.", "islocalized": "false", "uuidhistory": "71709697-2eda-4fe4-9160-e6a258ea6b0a\n0441380e-ef76-4ac6-b610-8c854edf11df", "preferredlabel": "make strategic business decisions"}, "revealed": true, "challenge": "Choisir une situation réelle ou fictive nécessitant une décision stratégique. Analyser les différentes options, évaluer les conséquences à court et long terme, et prendre une décision en justifiant le choix.", "is_anchor": true, "xp_reward": 20}, {"id": "skill::key_13533", "type": "skill", "depth": 0, "label": "Influencing Others", "notes": "", "state": "available", "visible": true, "graph_id": "e71a1975-1f8e-4e4b-9d3b-930a338bef5c", "metadata": {"type": "skill", "label": "motivate others", "node_id": "skill::key_13533", "altlabels": "inspire others\nmotivate others\nstimulate action\nenergise others\nempower others\nencourage others\nmotivating others\nmotivate staff and colleages", "originuri": "http://data.europa.eu/esco/skill/e2d44a9b-f28c-489e-9861-b654b5ded507", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "transversal", "description": "Direct other people''s behaviour by providing them with a convincing reason for action.", "islocalized": "false", "uuidhistory": "59bee618-e902-4c5f-af76-6e70b8b95df3\na8ca50f4-0f97-4961-8d3a-4a5f5f163790", "preferredlabel": "motivate others"}, "revealed": true, "challenge": "Le défi consiste à persuader un groupe de pairs de participer à une initiative communautaire. Cela pourrait être une collecte de fonds pour une œuvre caritative, l''organisation d''un événement environnemental, ou toute autre action bénéfique pour la communauté. L''objectif est de convaincre un minimum de 10 personnes de s''engager activement dans l''initiative.", "is_anchor": true, "xp_reward": 32}, {"id": "skill::key_1648", "type": "skill", "depth": 0, "label": "Problem Solving", "notes": "", "state": "available", "visible": true, "graph_id": "e71a1975-1f8e-4e4b-9d3b-930a338bef5c", "metadata": {"type": "skill", "label": "propose ICT solutions to business problems", "node_id": "skill::key_1648", "altlabels": "propose technical solutions to business problems\npropose ICT solutions to business problems", "originuri": "http://data.europa.eu/esco/skill/07e51c60-763a-4335-b4ec-70a15f66d328", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "cross-sector", "description": "Suggest how to solve business issues, using ICT means, so that business processes are improved.", "islocalized": "false", "uuidhistory": "57bfedf4-70e2-4736-a01e-ed696a50518a\n2949f643-88a5-411e-83d2-109f0749a45a", "preferredlabel": "propose ICT solutions to business problems"}, "revealed": true, "challenge": "Concevez et programmez un jeu de type escape room en utilisant des concepts algorithmiques tels que les algorithmes de recherche, de tri et de résolution de problèmes. Le jeu doit comporter plusieurs niveaux de difficulté et nécessitera une réflexion logique pour être résolu.", "is_anchor": true, "xp_reward": 26}, {"id": "skill::key_9586", "type": "skill", "depth": 0, "label": "Data Analysis", "notes": "", "state": "available", "visible": true, "graph_id": "e71a1975-1f8e-4e4b-9d3b-930a338bef5c", "metadata": {"type": "skill", "label": "data analytics", "node_id": "skill::key_9586", "altlabels": "data analytics", "originuri": "http://data.europa.eu/esco/skill/97bd1c21-66b2-4b7e-ad0f-e3cda590e378", "scopenote": "", "skilltype": "knowledge", "definition": "", "reuselevel": "cross-sector", "description": "The science of analysing and making decisions based on raw data collected from various sources. Includes knowledge of techniques using algorithms that derive insights or trends from that data to support decision-making processes.", "islocalized": "false", "uuidhistory": "ebe344b9-3c0a-4668-8a10-dd3f35f47ee2\n0b1b5779-e955-499f-a50d-e69ea698ba46", "preferredlabel": "data analytics"}, "revealed": true, "challenge": "Analyser les données de ventes mensuelles d''une entreprise sur les 12 derniers mois. Identifier les tendances, les variations saisonnières et les performances par produit ou service. Présenter les résultats sous forme de graphiques et de rapports.", "is_anchor": true, "xp_reward": 29}], "anchors": ["skill::key_9448", "skill::key_14598", "skill::key_13533", "skill::key_1648", "skill::key_9586"], "graph_id": "e71a1975-1f8e-4e4b-9d3b-930a338bef5c", "anchor_metadata": [{"id": "skill::key_9448", "score": 0.31065636900000004, "category": "leadership", "metadata": {"type": "skill", "label": "implement strategic management", "node_id": "skill::key_9448", "altlabels": "implement strategic management plan\ndeliver strategic management plan\ndevelop and implement strategic management plan\ndevise company development strategy\ndevise strategy for company development\ndevelop strategy for company development\nformulate and implement company development strategy\nimplement management strategy\nimplement strategic management principles\nformulate strategy for company development\nimplement strategic management", "originuri": "http://data.europa.eu/esco/skill/953445c0-4770-4be0-91cf-270a64c0e297", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "cross-sector", "description": "Implement a strategy for the development and transformation of the company. Strategic management involves the formulation and implementation of the major objectives and initiatives of a company by senior management on behalf of the owners, based on consideration of available resources and an assessment of the internal and external environments in which the organisation operates.", "islocalized": "false", "uuidhistory": "5ec05073-a8df-4a0e-9ab2-7721591dd3b6\nb0011391-93ed-4047-b65d-f977fabbe608", "preferredlabel": "implement strategic management"}, "confidence": 0.9, "esco_label": "Strategic Leadership", "applications": ["Developing and implementing long-term business strategies", "Leading cross-functional teams to drive innovation and growth", "Mentoring and coaching employees to foster a culture of entrepreneurship"], "justification": "Given the user''s interest in creating companies and their self-identification as a leader and inspirer, developing entrepreneurial leadership skills will allow them to lead and inspire others in complex business environments.", "original_label": "Entrepreneurial Leadership", "esco_description": "Strategic leadership involves the ability to set a clear vision, make sound decisions, and inspire others to achieve organizational goals. It requires effective communication, critical thinking, and the ability to adapt to changing business environments."}, {"id": "skill::key_14598", "score": 0.210788965, "category": "cognitive", "metadata": {"type": "skill", "label": "make strategic business decisions", "node_id": "skill::key_14598", "altlabels": "make tactical business decisions\npay per click\nmake strategic business decisions\nmake strategic business choices\nPPC", "originuri": "http://data.europa.eu/esco/skill/f60c9e52-95fc-4ca1-a73c-18a491153b63", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "cross-sector", "description": "Analyse business information and consult directors for decision making purposes in a varied array of aspects affecting the prospect, productivity and sustainable operation of a company. Consider the options and alternatives to a challenge and make sound rational decisions based on analysis and experience.", "islocalized": "false", "uuidhistory": "71709697-2eda-4fe4-9160-e6a258ea6b0a\n0441380e-ef76-4ac6-b610-8c854edf11df", "preferredlabel": "make strategic business decisions"}, "confidence": 0.85, "esco_label": "Strategic Decision Making", "applications": ["Developing business strategies based on market trends and competitor analysis", "Evaluating investment opportunities and making decisions on resource allocation", "Assessing risks and opportunities to guide organizational growth"], "justification": "As the user seeks to work in complex environments and desires to create meaningful impact, honing strategic decision-making skills will enable them to navigate the complexities of business and psychology, and contribute to creating valuable relationships between entities.", "original_label": "Strategic Decision Making", "esco_description": "The skill of Strategic Decision Making involves analyzing complex situations, identifying potential options, and making informed choices to achieve long-term organizational goals."}, {"id": "skill::key_13533", "score": 0.33204627, "category": "interpersonal", "metadata": {"type": "skill", "label": "motivate others", "node_id": "skill::key_13533", "altlabels": "inspire others\nmotivate others\nstimulate action\nenergise others\nempower others\nencourage others\nmotivating others\nmotivate staff and colleages", "originuri": "http://data.europa.eu/esco/skill/e2d44a9b-f28c-489e-9861-b654b5ded507", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "transversal", "description": "Direct other people''s behaviour by providing them with a convincing reason for action.", "islocalized": "false", "uuidhistory": "59bee618-e902-4c5f-af76-6e70b8b95df3\na8ca50f4-0f97-4961-8d3a-4a5f5f163790", "preferredlabel": "motivate others"}, "confidence": 0.8, "esco_label": "Influencing Others", "applications": ["Negotiating contracts and agreements", "Leading and managing teams", "Convincing stakeholders to support a proposal"], "justification": "Given the user''s ability to attract attention, make connections, and understand others'' motives, enhancing skills in interpersonal influence will enable them to effectively build and maintain relationships, a key aspect of their interest in creating meaningful connections between people and entities.", "original_label": "Interpersonal Influence", "esco_description": "Influencing others involves persuading, convincing, and motivating individuals or groups to take specific actions or adopt certain attitudes or behaviors. It requires effective communication, negotiation, and relationship-building skills."}, {"id": "skill::key_1648", "score": 0.39120119799999997, "category": "creative", "metadata": {"type": "skill", "label": "propose ICT solutions to business problems", "node_id": "skill::key_1648", "altlabels": "propose technical solutions to business problems\npropose ICT solutions to business problems", "originuri": "http://data.europa.eu/esco/skill/07e51c60-763a-4335-b4ec-70a15f66d328", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "cross-sector", "description": "Suggest how to solve business issues, using ICT means, so that business processes are improved.", "islocalized": "false", "uuidhistory": "57bfedf4-70e2-4736-a01e-ed696a50518a\n2949f643-88a5-411e-83d2-109f0749a45a", "preferredlabel": "propose ICT solutions to business problems"}, "confidence": 0.85, "esco_label": "Problem Solving", "applications": ["Developing new business models in the economics industry", "Designing and implementing cost-effective strategies for economic development", "Creating innovative solutions to optimize resource allocation in economic projects"], "justification": "Considering the user''s high creativity rating, developing creative problem-solving skills will leverage their natural strength to address complex challenges in the business and people-focused environments they aspire to work in.", "original_label": "Creative Problem Solving", "esco_description": "The capability to identify and address complex issues by generating innovative and effective solutions. This skill involves analyzing problems, thinking creatively, and implementing practical strategies."}, {"id": "skill::key_9586", "score": 0.33671799999999996, "category": "technical", "metadata": {"type": "skill", "label": "data analytics", "node_id": "skill::key_9586", "altlabels": "data analytics", "originuri": "http://data.europa.eu/esco/skill/97bd1c21-66b2-4b7e-ad0f-e3cda590e378", "scopenote": "", "skilltype": "knowledge", "definition": "", "reuselevel": "cross-sector", "description": "The science of analysing and making decisions based on raw data collected from various sources. Includes knowledge of techniques using algorithms that derive insights or trends from that data to support decision-making processes.", "islocalized": "false", "uuidhistory": "ebe344b9-3c0a-4668-8a10-dd3f35f47ee2\n0b1b5779-e955-499f-a50d-e69ea698ba46", "preferredlabel": "data analytics"}, "confidence": 0.8, "esco_label": "Data Analysis", "applications": ["Market research and trend analysis", "Financial forecasting and risk assessment", "Performance evaluation and optimization"], "justification": "To thrive in the economics and business domain, developing skills in data analysis and interpretation will provide the user with the necessary quantitative and analytical capabilities to contribute meaningfully in their field of study and work.", "original_label": "Data Analysis & Interpretation", "esco_description": "Ability to analyze and interpret data to extract meaningful insights and make informed decisions. Involves identifying trends, patterns, and relationships within datasets."}]}', '2025-06-09 21:37:04.405318');
INSERT INTO public.user_skill_trees (id, user_id, graph_id, tree_data, created_at) VALUES (33, 25, 'c70f3bd9-f1ab-4c41-a3a2-2c6cbdf072c5', '{"edges": [], "nodes": [{"id": "skill::key_7226", "type": "skill", "depth": 0, "label": "Strategic Thinking", "notes": "", "state": "available", "visible": true, "graph_id": "c70f3bd9-f1ab-4c41-a3a2-2c6cbdf072c5", "metadata": {"type": "skill", "label": "apply strategic thinking", "node_id": "skill::key_7226", "altlabels": "apply strategic thinking techniques\napply strategic thinking\napply techniques for strategic thinking\nmove strategically\nthink strategically", "originuri": "http://data.europa.eu/esco/skill/6c870993-9341-438b-91c0-c7fe4f96d8f5", "scopenote": "", "skilltype": "skill/competence", "definition": "", "reuselevel": "cross-sector", "description": "Apply generation and effective application of business insights and possible opportunities, in order to achieve competitive business advantage on a long-term basis.", "islocalized": "false", "uuidhistory": "a71b991a-32ab-4549-be36-4e1937acc883\n964c1d63-681d-4f91-9a0a-0ab87a57fcd8", "preferredlabel": "apply strategic thinking"}, "revealed": true, "challenge": "Organiser et animer une soirée de jeu de stratégie en temps réel impliquant au moins 10 participants. Chaque participant devra gérer des ressources, prendre des décisions stratégiques et négocier avec les autres joueurs pour atteindre ses objectifs.", "is_anchor": true, "xp_reward": 31}, {"id": "skill::key_6843", "type": "skill", "depth": 0, "label": "Entrepreneurship", "notes": "", "state": "available", "visible": true, "graph_id": "c70f3bd9-f1ab-4c41-a3a2-2c6cbdf072c5", "metadata": {"type": "skill", "label": "entrepreneurship", "node_id": "skill::key_6843", "altlabels": "entrepreneurship\nbusiness initiative\nentrepreneurialism", "originuri": "http://data.europa.eu/esco/skill/658605f2-1c95-49f0-bd98-0af7b15ad0b0", "scopenote": "", "skilltype": "knowledge", "definition": "", "reuselevel": "cross-sector", "descript