 {"id": "occupation::key_18148", "type": "occupation", "depth": 2, "label": "occupation::key_18148", "notes": "", "state": "locked", "visible": false, "graph_id": "5a1478de-2757-4edd-a8c0-d051cf2419fb", "metadata": {"code": "2511.9", "type": "occupation", "label": "ICT business analyst", "node_id": "occupation::key_18148", "altlabels": "ICT business analyst\nICT business analysts\nbusiness process specialist\nIT business analyst", "originuri": "http://data.europa.eu/esco/occupation/fe0fa514-b48d-4a53-9757-a283c0baacf0", "scopenote": "Excludes people performing development activities.", "definition": "", "description": "ICT business analysts are in charge of analysing and designing an organisation''s processes and systems, assessing the business model and its integration with technology. They also identify change needs, assess the impact of the change, capture and document requirements and then ensure that these requirements are delivered whilst supporting the business through the implementation process.", "islocalized": "false", "uuidhistory": "f163e862-fee0-4010-a717-6baba039227c\nc84230b4-e268-4567-b54c-f54e53126bdd", "occupationtype": "escooccupation", "preferredlabel": "ICT business analyst", "occupationgroupcode": "2511", "regulatedprofessionnote": "http://data.europa.eu/esco/regulated-professions/unregulated"}, "revealed": false, "challenge": "", "is_anchor": false, "xp_reward": 0, "similarity_score": 0.332122445}, {"id": "occupation::key_16236", "type": "occupation", "depth": 2, "label": "occupation::key_16236", "notes": "", "state": "locked", "visible": true, "graph_id": "5a1478de-2757-4edd-a8c0-d051cf2419fb", "metadata": {"code": "2434.2", "type": "occupation", "label": "ICT business development manager", "node_id": "occupation::key_16236", "altlabels": "IT commercial development manager\nIT business development manager\nICT commercial development manager\nICT business development manager\nICT business development managers", "originuri": "http://data.europa