localized": "false", "uuidhistory": "bf5c0618-497d-40f8-8320-5492cafc2f51\n4728caf7-b388-44e8-8b5d-792dfeb94a12", "preferredlabel": "psychological counselling methods"}, "revealed": false, "challenge": "", "is_anchor": false, "xp_reward": 25, "similarity_score": 0.5}, {"id": "occupation::key_17677", "type": "occupation", "depth": 3, "label": "assistant clinical psychologist", "notes": "", "state": "locked", "visible": false, "graph_id": "16b67717-a56b-48e2-ba7e-a855dee748d0", "metadata": {"code": "3259.2", "type": "occupation", "label": "assistant clinical psychologist", "altlabels": "assistant psychologist\npsychology assistant\npsychological assistant\npersonality assessment coordinator\nassistant clinical psychologist", "originuri": "http://data.europa.eu/esco/occupation/d1b8c046-3867-423a-84fd-41f7be3a6d29", "scopenote": "Excludes <a resource=\"http://data.europa.eu/esco/occupation/52ded7d7-11df-42e3-b90a-d7f4b70fb4b9\" typeOf=\"http://data.europa.eu/esco/model#Occupation\" href=\"http://data.europa.eu/esco/occupation/52ded7d7-11df-42e3-b90a-d7f4b70fb4b9\"><span property=\"http://www.w3.org/2000/01/rdf-schema#label\" xml:lang=\"en\">psychologist</span></a>.", "definition": "", "description": "Assistant clinical psychologists aid psychologists in their work. They work in healthcare facilities or private practices where they assist psychologists with their treatment of patients. Assistant clinical psychologists are healthcare professionals that can assess patients with psychological tests and aid with therapy, as well as performing administrative functions.", "islocalized": "false", "uuidhistory": "3fc33926-5a94-498d-bc9d-2c1c8df115ec\n334088d7-38c5-46cb-a6d9-a24293939293", "occupationtype": "escooccupation", "preferredlabel": "assistant clinical psychologist", "occupationgroupcode": "3259", "regulatedprofessionnote": "http://data.europa.eu/esco/regulated-professions/unregulated"}, "revealed": false, "challenge": "", "is_anchor": false, "xp_reward": 25, "similarit