challenge": "", "is_anchor": false, "xp_reward": 25, "similarity_score": 0.5}, {"id": "occupation::key_16140", "type": "occupation", "depth": 1, "label": "industrial robot controller", "notes": "", "state": "available", "visible": true, "graph_id": "423de973-5e42-42e1-a7fd-bd0f1035f429", "metadata": {"code": "3139.2", "type": "occupation", "label": "industrial robot controller", "altlabels": "industrial robot operative\nindustrial robot controller\ndelta robot controller\nrobotic equipment operative\nindustrial robotics controller\nrobotic equipment controller\nrobotic welder programmer\nindustrial robot operator\nrobot welder programmer\nindustrial robot test technician\nscara robot controller\nindustrial robot setter\nindustrial robot technician\nrobotic equipment operator", "originuri": "http://data.europa.eu/esco/occupation/5001506f-dd7d-4801-92ac-6f7e93b45133", "scopenote": "", "definition": "", "description": "Industrial robot controllers operate and monitor industrial robots used in automation processes to perform various manufacturing activities such as lifting, welding and assembling. They ensure that the machines are working correctly and in sync with other industrial robots, maintain and repair defective parts, assess risks and perform tests.", "islocalized": "false", "uuidhistory": "c098299f-0b49-4b49-b87e-6a7b931c0889\n47dfbdb2-e834-4e39-bcd2-35245978137f", "occupationtype": "escooccupation", "preferredlabel": "industrial robot controller", "occupationgroupcode": "3139", "regulatedprofessionnote": "http://data.europa.eu/esco/regulated-professions/unregulated"}, "revealed": true, "challenge": "", "is_anchor": false, "xp_reward": 25, "similarity_score": 0.5}, {"id": "occupation::key_17738", "type": "occupation", "depth": 1, "label": "production engineer", "notes": "", "state": "available", "visible": true, "graph_id": "423de973-5e42-42e1-a7fd-bd0f1035f429", "metadata": {"code": "2141.4.2", "type": "occupation", "label": "production engineer", "altlabels":